import { cleanText } from "../../../shared/apiError";
import type { TransferQrDto } from "../lib/api";

/** VietQR for bank transfer, generated by the server with amount and transfer content filled in. */
export function TransferQrCard({ qr, loading, error, onCopy }: {
  qr: TransferQrDto | null;
  loading?: boolean;
  error?: string | null;
  onCopy?: (value: string, message: string) => void;
}) {
  if (cleanText(error)) return <div className="error-box" role="alert">{cleanText(error)}</div>;
  if (loading || !qr) return <p className="muted" role="status">Đang tạo mã QR…</p>;
  return (
    <div className="qr-payment-panel">
      <div className="qr-payment-preview">
        <img src={`data:image/png;base64,${qr.qrPngBase64}`} alt={`Mã VietQR chuyển khoản ${qr.amount.toLocaleString("vi-VN")} đ`} />
      </div>
      <div className="qr-payment-details">
        <div className="qr-payment-summary"><span>Ngân hàng</span><strong>{qr.bankName}</strong></div>
        <div className="qr-payment-summary"><span>Chủ tài khoản</span><strong>{qr.accountName}</strong></div>
        <div className="qr-payment-summary"><span>Số tài khoản</span><strong>{qr.accountNumber}</strong></div>
        <div className="qr-payment-summary"><span>Số tiền</span><strong>{qr.amount.toLocaleString("vi-VN")} đ</strong></div>
        <div className="qr-payment-summary qr-payment-reference"><span>Nội dung chuyển khoản</span><strong>{qr.content}</strong></div>
        {onCopy ? (
          <div className="qr-payment-actions">
            <button className="cashier-button-outline" onClick={() => onCopy(qr.accountNumber, "Đã sao chép số tài khoản.")}>
              <i className="bi bi-copy me-1" />
              Sao chép STK
            </button>
            <button className="cashier-button-outline" onClick={() => onCopy(qr.content, "Đã sao chép nội dung chuyển khoản.")}>
              <i className="bi bi-copy me-1" />
              Sao chép nội dung
            </button>
          </div>
        ) : null}
        <div className="cashier-info-note qr-payment-note">
          Khách quét mã bằng ứng dụng ngân hàng: số tài khoản, số tiền và nội dung đã điền sẵn. Chỉ bấm
          "Đã nhận chuyển khoản" sau khi kiểm tra tiền đã vào tài khoản.
        </div>
      </div>
    </div>
  );
}
